             ReaderState::Starting{start} => {
                 &&& start == self.local_versions[node_id]
                 &&& start <= self.tail
             }
             ReaderState::Range{start, end, cur} => {
                 &&& self.local_versions[node_id] == start
                 &&& start <= end
                 &&& (self.tail as int) - (self.buffer_size as int) <= end <= (self.tail as int)
